use crate::history::{HistoryQuery,HistoryResult};
use serde::Serialize;
#[derive(Serialize)]struct Envelope<'a>{#[serde(rename="schemaVersion")]schema_version:u8,exported_at:i64,query:&'a HistoryQuery,points:&'a Vec<crate::history::HistoryPoint>,billing:&'a Vec<crate::history::BillingEntry>}
pub fn history_json(result:&HistoryResult,q:&HistoryQuery,at:i64)->Result<Vec<u8>,serde_json::Error>{serde_json::to_vec(&Envelope{schema_version:1,exported_at:at,query:q,points:&result.points,billing:&result.billing})}
pub fn history_csv(result:&HistoryResult)->Result<Vec<u8>,csv::Error>{let mut w=csv::Writer::from_writer(Vec::new());w.write_record(["provider","window_kind","sampled_at","used_percent","model","api_calls","estimated_cost_micros","overage_cost_micros"])?;for p in &result.points{w.write_record([p.provider.clone(),p.window_kind.clone(),p.sampled_at.to_string(),p.used_percent.to_string(),p.model.clone().unwrap_or_default(),p.api_calls.map(|v|v.to_string()).unwrap_or_default(),p.estimated_cost_micros.map(|v|v.to_string()).unwrap_or_default(),p.overage_cost_micros.map(|v|v.to_string()).unwrap_or_default()])?;}Ok(w.into_inner().map_err(|e|e.into_error())?)}
#[cfg(test)]mod tests{use super::*;#[test]fn csv_has_stable_columns_and_blank_nulls(){let r=HistoryResult{points:vec![crate::history::HistoryPoint{provider:"claude".into(),window_kind:"session_5h".into(),sampled_at:1000,used_percent:25.,model:None,api_calls:None,estimated_cost_micros:None,overage_cost_micros:None}],billing:vec![]};let t=String::from_utf8(history_csv(&r).unwrap()).unwrap();assert!(t.lines().next().unwrap().starts_with("provider,window_kind,sampled_at"));assert!(t.contains("claude,session_5h,1000,25"));}}
